CREATE TABLE products (id UUID PRIMARY KEY,sku VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL,description VARCHAR(2000),price NUMERIC(19,2) NOT NULL CHECK(price>0),currency VARCHAR(3) NOT NULL CHECK(currency='ZAR'),available_stock INTEGER NOT NULL CHECK(available_stock>=0),version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE reservations (id UUID PRIMARY KEY,state VARCHAR(30) NOT NULL CHECK(state IN ('HELD','COMMITTED','RELEASED')),request_hash TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
